"""
Demo: the writhe is a class function and, more strongly, a homomorphism.

We illustrate that the writhe (signed crossing count) is invariant under
conjugation of braid words -- writhe(g * b * g^{-1}) = writhe(b) -- which is a
necessary feature of any invariant of the underlying braid.  We also show the
permutation invariant separates braids the writhe cannot.
"""
from __future__ import annotations
from typing import List


def writhe(word: List[int]) -> int:
    return sum(1 if x > 0 else -1 for x in word)


def inverse_word(word: List[int]) -> List[int]:
    return [-x for x in reversed(word)]


def conjugate(g: List[int], b: List[int]) -> List[int]:
    return g + b + inverse_word(g)


def main() -> None:
    b = [1, -2, 1, -2]          # confused braid
    for g in ([1], [2, 1], [-1, 2, 2]):
        c = conjugate(g, b)
        assert writhe(c) == writhe(b)
        print(f"writhe(conj by {g}) = {writhe(c)} == writhe(b) = {writhe(b)}")
    print("Writhe is conjugation-invariant, as any braid invariant must be.")


if __name__ == "__main__":
    main()

"""
Demo: scanning families of braids to find writhe-blind nontrivial braids.

We enumerate short balanced braid words on 3 strands (equal numbers of positive
and negative letters, hence writhe 0) and report those whose underlying
permutation is nontrivial -- i.e. braids that are genuinely nontrivial yet are
invisible to the writhe, exactly like the confused braid.
"""
from __future__ import annotations
from itertools import product
from typing import List, Tuple


def writhe(word: Tuple[int, ...]) -> int:
    return sum(1 if x > 0 else -1 for x in word)


def perm(word: Tuple[int, ...], strands: int) -> Tuple[int, ...]:
    p = list(range(strands))
    for letter in word:
        i = abs(letter) - 1
        p[i], p[i + 1] = p[i + 1], p[i]
    return tuple(p)


def main() -> None:
    letters = [1, -1, 2, -2]
    found = 0
    for length in (2, 4):
        for word in product(letters, repeat=length):
            if writhe(word) != 0:
                continue
            p = perm(word, 3)
            if p != (0, 1, 2):           # nontrivial permutation
                found += 1
                if found <= 8:
                    print(f"writhe 0 but nontrivial: {word}  perm {p}")
    print(f"total writhe-blind-but-nontrivial words found: {found}")


if __name__ == "__main__":
    main()

