function WRITHE(word):
    total <- 0
    for each letter g in word:
        if g is a positive generator: total <- total + 1
        else (g is an inverse):        total <- total - 1
    return total

function UNDERLYING_PERMUTATION(word, strands):
    p <- identity permutation on {0,...,strands-1}
    for each letter g in word (left to right):
        i <- generator index of g
        swap p[i] and p[i+1]
    return p

function IS_CERTIFIABLY_NONTRIVIAL(word, strands):
    p <- UNDERLYING_PERMUTATION(word, strands)
    for k in 0..strands-1:
        if p[k] != k: return True
    return False
